package com.copiosa.domain.vocab.freq

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Covers the bundled frequency lists and the parsing that turns them into rank lookups.
 *
 * The shipped data is generated by `tools/build_frequency.py`, so the tests that matter are the ones
 * that would catch a bad regeneration rather than a bad parse: that the Kotlin and the committed TSV
 * still agree, and that no surface form is claimed by two headwords — which would make a card's rank
 * depend on map insertion order.
 */
class FrequencyListTest {

    private val es = requireNotNull(FrequencyLists.forTag("es"))

    // --- parsing ------------------------------------------------------------

    @Test
    fun `parses entries in rank order`() {
        val list = FrequencyList { listOf("ser|verb|es,era,fue", "casa|noun|casa,casas", "gato|noun|gato,gatos") }

        assertEquals(3, list.size)
        assertEquals(listOf("ser", "casa", "gato"), list.entries.map { it.lemma })
        assertEquals(listOf(1, 2, 3), list.entries.map { it.rank })
        assertEquals("verb", list.entries[0].pos)
    }

    @Test
    fun `every listed surface form resolves to its headword's rank`() {
        val list = FrequencyList { listOf("ser|verb|es,era,fue", "gato|noun|gato,gatos") }

        assertEquals(1, list.rankOfForm("es"))
        assertEquals(1, list.rankOfForm("era"))
        assertEquals(1, list.rankOfForm("fue"))
        assertEquals(2, list.rankOfForm("gatos"))
        // The headword itself always resolves, even when the generator listed no forms for it.
        assertEquals(1, list.rankOfForm("ser"))
        assertNull(list.rankOfForm("murciélago"))
    }

    @Test
    fun `lookup is normalized the same way highlighting is`() {
        val list = FrequencyList { listOf("día|noun|día,días") }

        assertEquals(1, list.rankOfForm("DÍA"))
        assertEquals(1, list.rankOfForm("  días "))
        // normalizeWord trims non-alphanumerics, so surrounding punctuation is not a miss.
        assertEquals(1, list.rankOfForm("¿día?"))
    }

    @Test
    fun `through returns the head of the list only`() {
        val list = FrequencyList { (1..10).map { "w$it|noun|w$it" } }

        assertEquals(3, list.through(3).size)
        assertEquals(listOf("w1", "w2", "w3"), list.through(3).map { it.lemma })
        assertEquals(10, list.through(999).size)
    }

    // --- buckets ------------------------------------------------------------

    @Test
    fun `bucket boundaries are inclusive of their max rank`() {
        assertEquals(FrequencyBucket.TOP_100, FrequencyBucket.forRank(1))
        assertEquals(FrequencyBucket.TOP_100, FrequencyBucket.forRank(100))
        assertEquals(FrequencyBucket.TOP_250, FrequencyBucket.forRank(101))
        assertEquals(FrequencyBucket.TOP_250, FrequencyBucket.forRank(250))
        assertEquals(FrequencyBucket.TOP_500, FrequencyBucket.forRank(251))
        assertEquals(FrequencyBucket.TOP_1K, FrequencyBucket.forRank(1000))
        assertEquals(FrequencyBucket.TOP_2K, FrequencyBucket.forRank(2000))
        // Outside the list entirely — no chip, no boost.
        assertNull(FrequencyBucket.forRank(2001))
    }

    // --- the shipped data ---------------------------------------------------

    @Test
    fun `both bundled languages load, and nothing else claims to`() {
        assertNotNull(FrequencyLists.forTag("es"))
        assertNotNull(FrequencyLists.forTag("pt"))
        // Region subtags resolve to the base language, as elsewhere in the app.
        assertNotNull(FrequencyLists.forTag("pt-PT"))
        assertNotNull(FrequencyLists.forTag("ES"))
        // A language with a picker entry but no bundled data must degrade to "no feature".
        assertNull(FrequencyLists.forTag("fr"))
        assertNull(FrequencyLists.forTag("de"))
    }

    @Test
    fun `the generated Spanish list matches the committed TSV`() {
        val tsv = readTsv("frequency_es.tsv")
        assertEquals(tsv.size, es.size)
        tsv.forEach { (rank, lemma, pos) ->
            val entry = es.entries[rank - 1]
            assertEquals("rank $rank lemma", lemma, entry.lemma)
            assertEquals("rank $rank pos", pos, entry.pos)
            assertEquals("rank $rank rank", rank, entry.rank)
        }
    }

    @Test
    fun `the generated Portuguese list matches the committed TSV`() {
        val pt = requireNotNull(FrequencyLists.forTag("pt"))
        val tsv = readTsv("frequency_pt.tsv")
        assertEquals(tsv.size, pt.size)
        tsv.forEach { (rank, lemma, _) -> assertEquals(lemma, pt.entries[rank - 1].lemma) }
    }

    @Test
    fun `no surface form is claimed by two headwords`() {
        // The generator asserts this too, but a hand-edit of the packed data would slip past it, and
        // a duplicate makes rankOfForm depend on which entry happened to be written last.
        for (lang in listOf("es", "pt")) {
            val seen = HashMap<String, String>()
            readTsvForms("frequency_$lang.tsv").forEach { (lemma, forms) ->
                forms.forEach { form ->
                    val owner = seen.put(form, lemma)
                    assertNull("$lang: '$form' claimed by both $owner and $lemma", owner)
                }
            }
        }
    }

    @Test
    fun `the head of the Spanish list is content vocabulary, not grammar`() {
        // A regression here means the generator's closed-class filter has broken: articles,
        // possessives and prepositions are the corpus's most frequent words by a wide margin, so if
        // any of them is present it will be at the very top.
        val head = es.entries.take(200).map { it.lemma }.toSet()
        listOf("el", "la", "de", "que", "no", "un", "para", "por", "mi", "su", "este", "como")
            .forEach { assertTrue("grammar word '$it' leaked into the list", it !in head) }
        // And the words that should lead do.
        listOf("ser", "estar", "tener", "hacer", "poder")
            .forEach { assertTrue("expected '$it' near the top", it in head) }
    }

    @Test
    fun `known homographs stay on the right headword`() {
        // Each of these was resolved wrongly by an earlier version of the generator: the noun was
        // swallowed by a rare verb that happens to share a conjugated form.
        assertNotNull("casa should be its own noun", es.entries.find { it.lemma == "casa" })
        assertNotNull("caso should be its own noun", es.entries.find { it.lemma == "caso" })
        assertNull("mercar is a mis-analysis of mercado", es.entries.find { it.lemma == "mercar" })
        assertNull("gravar is a mis-analysis of grave", es.entries.find { it.lemma == "gravar" })
        // And the reverse: inflections must roll up rather than stand alone.
        assertEquals(es.rankOfForm("ser"), es.rankOfForm("es"))
        assertEquals(es.rankOfForm("ser"), es.rankOfForm("fue"))
        assertEquals(es.rankOfForm("estar"), es.rankOfForm("estoy"))
        assertEquals(es.rankOfForm("tener"), es.rankOfForm("tengo"))
    }

    // --- helpers ------------------------------------------------------------

    /** (rank, lemma, pos) from a committed list, skipping the `#` header lines. */
    private fun readTsv(name: String): List<Triple<Int, String, String>> =
        resourceLines(name).map { line ->
            val f = line.split("\t")
            Triple(f[0].toInt(), f[1], f[2])
        }

    private fun readTsvForms(name: String): List<Pair<String, List<String>>> =
        resourceLines(name).map { line ->
            val f = line.split("\t")
            f[1] to (f.getOrNull(3)?.split(",")?.filter { it.isNotEmpty() } ?: emptyList())
        }

    private fun resourceLines(name: String): List<String> {
        val stream = requireNotNull(javaClass.classLoader?.getResourceAsStream(name)) {
            "missing test resource $name — run tools/build_frequency.py"
        }
        return stream.bufferedReader().readLines().filter { it.isNotBlank() && !it.startsWith("#") }
    }
}
